"""Manuel français embarqué. Aucun accès réseau ni dépendance au moteur audio.

Chaque chapitre possède un identifiant stable pour les liens et une liste de
sections (titre, HTML Qt). Les sources de vérification figurent dans le rapport
doc/help_audit.md. Garder les raccourcis synchronisés avec les tests d'inventaire.
"""
from dataclasses import dataclass
from html import escape
from html.parser import HTMLParser
import unicodedata


@dataclass(frozen=True)
class Topic:
    id: str
    category: str
    title: str
    keywords: str
    sections: tuple
    related: tuple = ()


