TOPIC_BY_ID = {topic.id: topic for topic in TOPICS}


class _PlainText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []

    def handle_data(self, data):
        self.parts.append(data)


def plain_text(html):
    parser = _PlainText()
    parser.feed(html)
    return " ".join(parser.parts)


def normalize(text):
    return "".join(c for c in unicodedata.normalize("NFD", text.casefold())
                   if not unicodedata.combining(c))


def shortcut_html():
    sections = []
    for category in dict.fromkeys(row[2] for row in SHORTCUTS):
        rows = "".join(f"<tr><td><b>{escape(key)}</b></td><td>{escape(desc)}</td></tr>"
                       for key, desc, scope in SHORTCUTS if scope == category)
        sections.append((category, f'<table width="95%" cellpadding="6">{rows}</table>'))
    return tuple(sections)


def sections_for(topic):
    return topic.sections + (shortcut_html() if topic.id == "shortcuts" else ())


def search_topics(query):
    words = normalize(query).split()
    return [topic for topic in TOPICS if all(word in normalize(
        topic.title + " " + topic.category + " " + topic.keywords + " " +
        " ".join(title + " " + plain_text(body) for title, body in sections_for(topic)))
        for word in words)]


def render_topic(topic):
    sections = sections_for(topic)
    toc = " · ".join(f'<a href="#section-{i}">{escape(title)}</a>'
                     for i, (title, _) in enumerate(sections))
    body = "".join(f'<h2 id="section-{i}"><a name="section-{i}"></a>{escape(title)}</h2>{html}'
                   for i, (title, html) in enumerate(sections))
    related = " · ".join(f'<a href="help:{key}">{escape(TOPIC_BY_ID[key].title)}</a>'
                         for key in topic.related)
    return (f'<html><head><style>body {{ color: #e2e8f0; font-family: "Segoe UI"; }} '
            'h1, a { color: #38bdf8; } h2 { color: #6ee7b7; margin-top: 22px; } '
            'p, li { line-height: 145%; } td { border-bottom: 1px solid #34384b; }'
            '</style></head><body>'
            f'<p>{escape(topic.category)}</p><h1>{escape(topic.title)}</h1>'
            f'<p><b>Dans ce chapitre</b><br>{toc}</p>{body}'
            + (f'<hr><p><b>Pour continuer</b><br>{related}</p>' if related else '')
            + '</body></html>')
